cat > tests/max_message_bytes.rs <<'E'
mod common;

use common::Harness;
use serde_json::json;

fn create(h: &mut Harness, name: &str, max: u64) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": {"MaxMessageBytes": max}}));
}

fn send(h: &mut Harness, body: &str) -> serde_json::Value {
    h.run(json!({"Command": "SendMessage", "QueueName": "q", "Body": body}))
}

#[test]
fn attribute_range_and_default() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        assert_eq!(
            h.err(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": bad}})),
            "InvalidParameterValue"
        );
    }
    create(&mut h, "q", 1);
    create(&mut h, "r", 1024);
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1);
}

#[test]
fn body_limit_counts_utf8_bytes() {
    let mut h = Harness::new();
    create(&mut h, "q", 4);
    assert_eq!(send(&mut h, "abcd")["ok"], true);
    assert_eq!(send(&mut h, "abcde")["error"]["code"], "InvalidParameterValue");
    // two characters, four bytes
    assert_eq!(send(&mut h, "éé")["ok"], true);
    // three characters, six bytes
    assert_eq!(send(&mut h, "ééé")["error"]["code"], "InvalidParameterValue");
}

#[test]
fn limit_rule_comes_before_other_send_rules() {
    let mut h = Harness::new();
    create(&mut h, "q", 2);
    // standard queue + GroupId would be UnsupportedOperation, but the size rule is first
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "abc", "GroupId": "g"})),
        "InvalidParameterValue"
    );
}

#[test]
fn set_attributes_and_create_idempotence() {
    let mut h = Harness::new();
    create(&mut h, "q", 3);
    create(&mut h, "q", 3);
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q"})),
        "QueueAlreadyExists"
    );
    assert_eq!(send(&mut h, "abc")["ok"], true);
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    // existing message untouched
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "abc");
    assert_eq!(send(&mut h, "ab")["error"]["code"], "InvalidParameterValue");
}

#[test]
fn dead_letter_moves_ignore_the_limit() {
    let mut h = Harness::new();
    create(&mut h, "dlq", 1);
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {
        "DeadLetterQueue": "dlq", "MaxReceiveCount": 1, "VisibilityTimeout": 0}}));
    assert_eq!(send(&mut h, "long body")["ok"], true);
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dlq"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
}
E
