mod common;

use common::Harness;
use serde_json::json;

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tags(h: &mut Harness) -> serde_json::Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn starts_empty_and_sets_and_replaces() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "B": ""}}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "2", "b": "x"}}));
    assert_eq!(tags(&mut h), json!({"a": "2", "B": "", "b": "x"}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {}}));
}

#[test]
fn untag_ignores_missing_keys() {
    let mut h = setup();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "b": "2"}}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]}));
    assert_eq!(tags(&mut h), json!({"b": "2"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
}

#[test]
fn value_and_key_validation() {
    let mut h = setup();
    let tag = |t: serde_json::Value| json!({"Command": "TagQueue", "QueueName": "q", "Tags": t});
    assert_eq!(h.err(tag(json!({"a": 1}))), "InvalidParameterValue");
    assert_eq!(h.err(tag(json!({"a": null}))), "InvalidParameterValue");
    assert_eq!(h.err(tag(json!({"a b": "x"}))), "InvalidParameterValue");
    assert_eq!(h.err(tag(json!({"": "x"}))), "InvalidParameterValue");
    assert_eq!(h.err(tag(json!({"k".repeat(129): "x"}))), "InvalidParameterValue");
    h.ok(tag(json!({"k".repeat(128): "v".repeat(256)})));
    assert_eq!(h.err(tag(json!({"a": "v".repeat(257)}))), "InvalidParameterValue");
    // 129 bytes of two-byte characters: 258 bytes
    assert_eq!(h.err(tag(json!({"a": "é".repeat(129)}))), "InvalidParameterValue");
    h.ok(tag(json!({"a": "é".repeat(128)})));
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": [1]})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a b"]})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": "a"})),
        "InvalidParameterValue"
    );
}

#[test]
fn check_order() {
    let mut h = setup();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    // value errors (step 3) come before the queue lookup (step 4)
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": 1}})),
        "InvalidParameterValue"
    );
    assert_eq!(
        h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}})),
        "QueueDoesNotExist"
    );
    assert_eq!(
        h.err(json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []})),
        "QueueDoesNotExist"
    );
    assert_eq!(
        h.err(json!({"Command": "ListQueueTags", "QueueName": "nope"})),
        "QueueDoesNotExist"
    );
}

#[test]
fn fifty_tag_limit_counts_only_new_keys() {
    let mut h = setup();
    let many = |range: std::ops::Range<u32>| {
        let t: serde_json::Map<_, _> = range.map(|i| (format!("k{i}"), json!("v"))).collect();
        json!({"Command": "TagQueue", "QueueName": "q", "Tags": t})
    };
    h.ok(many(0..50));
    assert_eq!(h.err(many(49..51)), "LimitExceeded");
    // failed command changed nothing
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 50);
    // replacing existing keys is fine at the limit
    h.ok(many(0..50));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k0"]}));
    h.ok(many(50..51));
    assert_eq!(h.err(many(0..1)), "LimitExceeded");
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"x": "1", "y": "2"}})), "LimitExceeded");
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1"}}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(attrs["Attributes"].get("Tags").is_none());
    // CreateQueue rule 4 ignores tags
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h), json!({}));
}
