mod common;

use common::Harness;
use serde_json::{Value, json};

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn send_batch(entries: Value) -> Value {
    json!({"Command": "SendMessageBatch", "QueueName": "q", "Entries": entries})
}

fn delete_batch(entries: Value) -> Value {
    json!({"Command": "DeleteMessageBatch", "QueueName": "q", "Entries": entries})
}

#[test]
fn send_batch_succeeds_in_order() {
    let mut h = setup();
    let r = h.ok(send_batch(json!([
        {"Id": "a", "Body": "one"}, {"Id": "b", "Body": "two", "DelaySeconds": 5}
    ])));
    assert_eq!(
        r["Successful"],
        json!([{"Id": "a", "MessageId": "m-1"}, {"Id": "b", "MessageId": "m-2"}])
    );
    assert_eq!(r["Failed"], json!([]));
    let c = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(c["Counts"], json!({"Visible": 1, "InFlight": 0, "Delayed": 1}));
}

#[test]
fn entry_failures_do_not_stop_others_and_use_no_message_id() {
    let mut h = setup();
    let r = h.ok(send_batch(json!([
        {"Id": "a", "Body": "one"},
        {"Id": "b"},
        {"Id": "c", "Body": ""},
        {"Id": "d", "Body": "x", "GroupId": "g"},
        {"Id": "e", "Body": "two"},
    ])));
    assert_eq!(
        r["Successful"],
        json!([{"Id": "a", "MessageId": "m-1"}, {"Id": "e", "MessageId": "m-2"}])
    );
    let failed = r["Failed"].as_array().unwrap();
    let got: Vec<(&str, &str)> = failed
        .iter()
        .map(|f| (f["Id"].as_str().unwrap(), f["error"]["code"].as_str().unwrap()))
        .collect();
    assert_eq!(
        got,
        [
            ("b", "MissingParameter"),
            ("c", "InvalidParameterValue"),
            ("d", "UnsupportedOperation")
        ]
    );
    assert!(failed[0]["error"]["message"].is_string());
}

#[test]
fn all_entries_failing_is_still_a_success() {
    let mut h = setup();
    let r = h.ok(send_batch(json!([{"Id": "a"}])));
    assert_eq!(r["Successful"], json!([]));
    assert_eq!(r["Failed"][0]["error"]["code"], "MissingParameter");
}

#[test]
fn batch_rules_and_check_order() {
    let mut h = setup();
    assert_eq!(h.err(send_batch(json!([]))), "EmptyBatchRequest");
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    assert_eq!(h.err(send_batch(json!(eleven))), "TooManyEntriesInBatchRequest");
    let ten: Vec<Value> = (0..10).map(|i| json!({"Id": format!("i{i}"), "Body": "x"})).collect();
    assert_eq!(h.ok(send_batch(json!(ten)))["Successful"].as_array().unwrap().len(), 10);

    for bad in [
        json!([1]), json!(["a"]), json!([null]), json!([{"Body": "x"}]),
        json!([{"Id": 1, "Body": "x"}]), json!([{"Id": null, "Body": "x"}]),
        json!([{"Id": "", "Body": "x"}]), json!([{"Id": "a b", "Body": "x"}]),
        json!([{"Id": "a".repeat(81), "Body": "x"}]),
        // an invalid Id wins over duplicate Ids
        json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "x"}, {"Id": "!"}]),
    ] {
