#[test]
fn delete_batch() {
    let mut h = setup();
    h.ok(send_batch(json!([{"Id": "a", "Body": "1"}, {"Id": "b", "Body": "2"}])));
    let got = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 2}));
